{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Theophylline, the unsubstituted 1,3-dimethylxanthine core, has essentially 100% absolute oral bioavailability in healthy subjects, showing that the xanthine scaffold is very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paraxanthine, a dimethylxanthine, is rapidly and completely absorbed with high bioavailability in healthy adults, supporting high oral absorption for the xanthine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Temozolomide, a related N-heterocyclic drug, has absolute oral bioavailability close to 1 (AUC p.o./i.v. ≈ 1), demonstrating that this type of polar heterocycle can be essentially completely absorbed.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 7-substituted theophylline (xanthine) derivative. Close xanthine analogues such as theophylline and paraxanthine show essentially complete or high oral bioavailability, and a related N-heterocycle, temozolomide, is nearly 100% bioavailable. No mechanistically transferable low-F evidence outweighs this pattern, so the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for doxofylline itself is present in the supplied evidence.",
    "Low-F didanosine records were considered but not applied because the acid-labile nucleoside linkage is not shared by the xanthine core."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

